/* eslint-disable @typescript-eslint/no-require-imports */
const plugin = require('../plugins/with-release-signing') as {
  applyReleaseSigning(gradle: string): string;
  SIGNING_VARS: string[];
  MARKER: string;
};

/** The relevant part of android/app/build.gradle as generated by `expo prebuild` (Expo SDK 58 template). */
const TEMPLATE = `apply plugin: "com.android.application"

def enableMinifyInReleaseBuilds = (findProperty('android.enableMinifyInReleaseBuilds') ?: false).toBoolean()

android {
    namespace 'az.tezfiks.app'
    defaultConfig {
        applicationId 'az.tezfiks.app'
        versionCode 1
        versionName "0.1.0"
    }
    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }
    buildTypes {
        debug {
            signingConfig signingConfigs.debug
        }
        release {
            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            signingConfig signingConfigs.debug
            minifyEnabled enableMinifyInReleaseBuilds
        }
    }
}

dependencies {
    implementation("com.facebook.react:react-android")
}
`;

function block(gradle: string, name: 'debug' | 'release'): string {
  const types = gradle.slice(gradle.indexOf('buildTypes {'));
  const start = types.indexOf(`${name} {`);
  return types.slice(start, types.indexOf('}', start));
}

describe('with-release-signing config plugin (BUG-003)', () => {
  const out = plugin.applyReleaseSigning(TEMPLATE);

  it('signs the release build type with signingConfigs.release, not the debug key', () => {
    expect(block(out, 'release')).toContain('signingConfig signingConfigs.release');
    expect(block(out, 'release')).not.toContain('signingConfigs.debug');
  });

  it('keeps debug builds on the debug key for local development', () => {
    expect(block(out, 'debug')).toContain('signingConfig signingConfigs.debug');
    expect(out).toContain("storeFile file('debug.keystore')");
  });

  it('reads every signing value from Gradle properties or the environment, never a literal secret', () => {
    for (const v of plugin.SIGNING_VARS) expect(out).toContain(`'${v}'`);
    expect(out).toContain('System.getenv(name)');
    const release = out.slice(out.indexOf('        release {'), out.indexOf('buildTypes {'));
    expect(release).not.toMatch(/storePassword\s+'/);
    expect(release).not.toMatch(/keyPassword\s+'/);
  });

  it('fails release tasks when signing is not configured instead of producing a debug-signed or unsigned APK', () => {
    expect(out).toContain('gradle.taskGraph.whenReady');
    expect(out).toContain('throw new GradleException("Release signing is not configured.');
    expect(out).toMatch(/assemble\|bundle\|package\|install\|sign/);
  });

  it('does not change the application id or the version lines', () => {
    expect(out).toContain("applicationId 'az.tezfiks.app'");
    expect(out).toContain('versionCode 1');
  });

  it('is idempotent', () => {
    expect(plugin.applyReleaseSigning(out)).toBe(out);
  });

  it('refuses a template it does not recognise, so debug-signed releases cannot come back silently', () => {
    expect(() => plugin.applyReleaseSigning(TEMPLATE.replace(/release \{[\s\S]*?signingConfigs\.debug/, 'release {'))).toThrow(
      /buildTypes\.release/,
    );
    expect(() => plugin.applyReleaseSigning('apply plugin: "x"\n')).toThrow(/android \{ \}/);
  });
});
